HAL_StatusTypeDef HAL_UART_Abort(UART_HandleTypeDef *huart)
{
  /* Skip all hardware-specific interrupt disable operations */
  /* Original: ATOMIC_CLEAR_BIT(huart->Instance->CR1, (USART_CR1_RXNEIE | USART_CR1_PEIE | USART_CR1_TXEIE | USART_CR1_TCIE)); */
  /* Original: ATOMIC_CLEAR_BIT(huart->Instance->CR3, USART_CR3_EIE); */

  /* If Reception till IDLE event was ongoing, skip IDLEIE interrupt disable */
  if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
  {
    /* Skip hardware-specific atomic operation */
    /* Original: ATOMIC_CLEAR_BIT(huart->Instance->CR1, (USART_CR1_IDLEIE)); */
  }

  /* Skip DMA disable and abort operations for both Tx and Rx */
  /* Original code had hardware register checks and DMA abort calls */

  /* Reset Tx and Rx transfer counters */
  huart->TxXferCount = 0x00U;
  huart->RxXferCount = 0x00U;

  /* Reset ErrorCode */
  huart->ErrorCode = HAL_UART_ERROR_NONE;

  /* Restore huart->RxState and huart->gState to Ready */
  huart->RxState = HAL_UART_STATE_READY;
  huart->gState = HAL_UART_STATE_READY;
  huart->ReceptionType = HAL_UART_RECEPTION_STANDARD;

  return HAL_OK;
}
